/**
 * @summary Send or schedule an export email. Provide a file upload and/or `sourceKind`+`sourceId`
(currently `dep-export`). Large files are sent as a time-limited download link.
 */
export const postApiAdminExportEmailSend = (
  postApiAdminExportEmailSendBody?: PostApiAdminExportEmailSendBody,
  options?: SecondParameter<typeof customInstance>,
  signal?: AbortSignal
) => {
  const formData =
    postApiAdminExportEmailSendBody === undefined
      ? undefined
      : (() => {
          const formData = new FormData();
          if (postApiAdminExportEmailSendBody?.To !== undefined) {
            formData.append(`To`, postApiAdminExportEmailSendBody.To);
          }
          if (postApiAdminExportEmailSendBody?.Subject !== undefined) {
            formData.append(`Subject`, postApiAdminExportEmailSendBody.Subject);
          }
          if (postApiAdminExportEmailSendBody?.Message !== undefined) {
            formData.append(`Message`, postApiAdminExportEmailSendBody.Message);
          }
          if (postApiAdminExportEmailSendBody?.ScheduledForUtc !== undefined) {
            formData.append(`ScheduledForUtc`, postApiAdminExportEmailSendBody.ScheduledForUtc);
          }
          if (postApiAdminExportEmailSendBody?.SourceKind !== undefined) {
            formData.append(`SourceKind`, postApiAdminExportEmailSendBody.SourceKind);
          }
          if (postApiAdminExportEmailSendBody?.SourceId !== undefined) {
            formData.append(`SourceId`, postApiAdminExportEmailSendBody.SourceId);
          }
          if (postApiAdminExportEmailSendBody?.PreferLink !== undefined) {
            formData.append(`PreferLink`, postApiAdminExportEmailSendBody.PreferLink.toString());
          }
          if (postApiAdminExportEmailSendBody?.file !== undefined) {
            formData.append(`file`, postApiAdminExportEmailSendBody.file);
          }
          return formData;
        })();

  return customInstance<SendExportEmailResponse>(
    {
      url: `/api/admin/export-email/send`,
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      data: formData,
      signal,
    },
    options
  );
};

