/**
 * @summary Import demo products from uploaded CSV/Excel template for a tenant (super-admin).
 */
export const postApiAdminTenantsTenantIdDemoProductsTemplateImport = (
  tenantId: string,
  postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?: PostApiAdminTenantsTenantIdDemoProductsTemplateImportBody,
  options?: SecondParameter<typeof customInstance>,
  signal?: AbortSignal
) => {
  const formData =
    postApiAdminTenantsTenantIdDemoProductsTemplateImportBody === undefined
      ? undefined
      : (() => {
          const formData = new FormData();
          if (postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.file !== undefined) {
            formData.append(`file`, postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.file);
          }
          if (
            postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.overwriteExisting !==
            undefined
          ) {
            formData.append(
              `overwriteExisting`,
              postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.overwriteExisting.toString()
            );
          }
          if (
            postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.priceAdjustmentMode !==
            undefined
          ) {
            formData.append(
              `priceAdjustmentMode`,
              postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.priceAdjustmentMode
            );
          }
          if (
            postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.priceAdjustmentPercent !==
            undefined
          ) {
            formData.append(
              `priceAdjustmentPercent`,
              postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.priceAdjustmentPercent.toString()
            );
          }
          if (
            postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.priceRoundIncrement !==
            undefined
          ) {
            formData.append(
              `priceRoundIncrement`,
              postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.priceRoundIncrement.toString()
            );
          }
          if (postApiAdminTenantsTenantIdDemoProductsTemplateImportBody?.imageMode !== undefined) {
            formData.append(
              `imageMode`,
              postApiAdminTenantsTenantIdDemoProductsTemplateImportBody.imageMode
            );
          }
          return formData;
        })();

  return customInstance<ImportResult>(
    {
      url: `/api/admin/tenants/${tenantId}/demo-products/template/import`,
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      data: formData,
      signal,
    },
    options
  );
};

